INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 16, 155, 0, "ヒヨリ", "東山奈央", "トゥインクルウィッシュ", "獣人族", "人助け、応援", 8, 44, 2, 100101, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 27);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 158, 0, "ユイ", "種田梨沙", "トゥインクルウィッシュ", "ヒューマン", "料理、人間観察", 4, 47, 2, 100201, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 5);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 18, 163, 0, "レイ", "早見沙織", "トゥインクルウィッシュ", "魔族", "読書、乗馬、お茶", 1, 46, 2, 100301, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 12);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 9, 128, 0, "ミソギ", "諸星すみれ", "リトルリリカル", "ヒューマン", "いたずら、探検", 8, 27, 5, 100401, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 12, 146, 0, "マツリ", "下田麻美", "王宮騎士団（NIGHTMARE）", "獣人族", "ヒーローごっこ", 11, 40, 8, 100501, "？？？", "ヒーローに憧れる騎士見習いの少女", 25);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 13, 150, 0, "アカリ", "浅倉杏美", "悪魔偽王国軍（ディアボロス）", "魔族", "サックス", 11, 42, 7, 100601, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 130, 0, "ミヤコ", "雨宮天", "悪魔偽王国軍（ディアボロス）", "魔族", "プリンを食べること", 1, 32, 7, 100701, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", 23);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 150, 0, "ユキ", "大空直美", "ヴァイスフリューゲル　ランドソル支部", "エルフ", "鏡で自分を見ること", 10, 40, 15, 100801, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 159, 0, "アンナ", "髙野麻美", "トワイライトキャラバン", "魔族", "小説執筆", 7, 45, 13, 100901, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", 5);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 155, 0, "マホ", "内田真礼", "自警団（カォン）", "獣人族", "空想、ぬいぐるみ集め", 9, 42, 10, 101001, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 15, 156, 0, "リノ", "阿澄佳奈", "ラビリンス", "ヒューマン", "お裁縫", 8, 44, 3, 101101, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "人懐っこくてマシンガントークな妹系少女", 25);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 156, 0, "ハツネ", "大橋彩香", "フォレスティエ", "エルフ", "妹と遊ぶこと、二度寝、昼寝、早寝", 12, 46, 6, 101201, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "みんなのために超能力を使う眠り姫", 24);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 166, 0, "ナナカ", "佳村はるか", "トワイライトキャラバン", "魔族", "読書、魔法", 8, 55, 13, 101301, "", "オタク全開な魔法少女", 21);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 15, 152, 0, "カスミ", "水瀬いのり", "自警団（カォン）", "獣人族", "読書、推理", 11, 41, 10, 101401, "test", "頭脳明晰な美少女名探偵", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 21, 165, 0, "ミサト", "國府田マリ子", "フォレスティエ", "エルフ", "絵本作り", 9, 54, 6, 101501, "test", "母性溢れる優しいみんなの「ミサト先生」", 5);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 167, 0, "スズナ", "上坂すみれ", "ルーセント学院", "魔族", "ファッション", 4, 48, 14, 101601, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 158, 0, "カオリ", "高森奈津美", "自警団（カォン）", "獣人族", "踊り、空手", 7, 53, 10, 101701, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", 7);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 23, 162, 0, "イオ", "伊藤静", "ルーセント学院", "魔族", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 8, 52, 14, 101801, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", 14);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 10, 117, 0, "ミミ", "日高里菜", "リトルリリカル", "獣人族", "かわいいもの集め", 4, 21, 5, 102001, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 12, 150, 0, "クルミ", "植田佳奈", "サレンディア救護院", "ヒューマン", "観劇、おままごと", 6, 40, 9, 102101, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", 9);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 13, 150, 0, "ヨリ", "原紗友里", "悪魔偽王国軍（ディアボロス）", "魔族", "ゲーム全般", 11, 40, 7, 102201, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "人見知りであまのじゃくな女の子", 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 148, 0, "アヤネ", "芹澤優", "サレンディア救護院", "ヒューマン", "屋内でできる遊び", 5, 38, 9, 102301, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 15, 154, 0, "スズメ", "悠木碧", "サレンディア救護院", "ヒューマン", "ご奉仕", 12, 43, 9, 102501, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", 12);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 144, 0, "リン", "小岩井ことり", "牧場（エリザベスパーク）", "獣人族", "あんパン", 1, 42, 11, 102601, "test", "遊びと睡眠が何より大事なぐうたら娘", 1);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 16, 154, 0, "エリコ", "橋本ちなみ", "トワイライトキャラバン", "魔族", "実験、裁縫、料理", 7, 43, 13, 102701, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", 30);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 156, 0, "サレン", "堀江由衣", "サレンディア救護院", "エルフ", "経営、お茶会", 10, 43, 9, 102801, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", 4);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 157, 0, "ノゾミ", "日笠陽子", "カルミナ", "ヒューマン", "舞台鑑賞、ダンス", 1, 40, 4, 102901, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "歌って踊れる大人気アイドル", 24);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 163, 0, "ニノン", "佐藤聡美", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "忍法開発", 8, 51, 15, 103001, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", 31);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 157, 0, "シノブ", "大坪由佳", "悪魔偽王国軍（ディアボロス）", "魔族", "占い", 12, 42, 7, 103101, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 157, 0, "アキノ", "松嵜麗", "メルクリウス財団", "ヒューマン", "慈善事業", 3, 45, 12, 103201, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "一人前の商人を目指すパワフルお嬢様", 12);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 20, 142, 0, "マヒル", "新田恵海", "牧場（エリザベスパーク）", "ヒューマン", "漫才", 3, 35, 11, 103301, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "みんなを笑顔にするお笑い牧場主", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 22, 164, 0, "ユカリ", "今井麻美", "メルクリウス財団", "エルフ", "ウインドーショッピング", 3, 55, 12, 103401, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", 16);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 8, 118, 0, "キョウカ", "小倉唯", "リトルリリカル", "エルフ", "お勉強", 2, 21, 5, 103601, "test", "礼儀正しくしっかり者のちびっ子優等生", 2);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 13, 149, 0, "トモ", "茅原実里", "王宮騎士団（NIGHTMARE）", "ヒューマン", "剣術、年長者をからかう", 8, 43, 8, 103701, "test", "義理堅くてからかい好きな剣術少女", 11);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 153, 0, "シオリ", "小清水亜美", "牧場（エリザベスパーク）", "獣人族", "読書、お散歩", 11, 40, 11, 103801, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 13, 158, 0, "アオイ", "花澤香菜", "フォレスティエ", "エルフ", "友達作りのイメトレ", 6, 44, 6, 104001, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "「友達」に憧れる、エルフの森の女の子", 6);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 163, 0, "チカ", "福原綾香", "カルミナ", "ヒューマン", "各種楽器", 6, 46, 4, 104201, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 168, 0, "マコト", "小松未可子", "自警団（カォン）", "獣人族", "お菓子作り", 8, 54, 10, 104301, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "男勝りで情に厚いワイルド娘", 9);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", "??", 172, 0, "イリヤ", "丹下桜", "悪魔偽王国軍（ディアボロス）", "魔族", "世界征服", 5, 50, 7, 104401, "test", "かつては夜を支配した最強の吸血鬼", 5);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 157, 0, "クウカ", "長妻樹里", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "小説を読むこと", 11, 49, 15, 104501, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", 19);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 19, 158, 0, "タマキ", "沼倉愛美", "メルクリウス財団", "獣人族", "猫とたわむれること", 3, 48, 12, 104601, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 1);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 25, 171, 0, "ジュン", "川澄綾子", "王宮騎士団（NIGHTMARE）", "ヒューマン", "格闘技、湯浴み", 10, 50, 8, 104701, "？？？", "素顔を見せない冷静沈着な女性騎士", 25);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 20, 163, 0, "ミフユ", "田所あずさ", "メルクリウス財団", "ヒューマン", "傭兵などのアルバイト", 11, 49, 12, 104801, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", 11);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 168, 0, "シズル", "生天目仁美", "ラビリンス", "ヒューマン", "家事全般", 10, 54, 3, 104901, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 24);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 11, 120, 0, "ミサキ", "久野美咲", "ルーセント学院", "魔族", "ファッション誌鑑賞、コスメ集め", 1, 22, 14, 105001, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 27, 166, 0, "ミツキ", "三石琴乃", "トワイライトキャラバン", "ヒューマン", "研究、実験", 3, 53, 13, 105101, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", 7);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 150, 0, "リマ", "徳井青空", "牧場（エリザベスパーク）", "獣人族", "毛繕い、お喋り", 3, 100, 11, 105201, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "乙女チックなもふもふアニマル", 14);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 140, 0, "モニカ", "辻あゆみ", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "お菓子屋通い", 7, 33, 15, 105301, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", 28);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 153, 0, "ツムギ", "木戸衣吹", "カルミナ", "ヒューマン", "裁縫", 9, 45, 4, 105401, "test", "ファッション大好きなキュートガール", 7);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 155, 0, "アユミ", "大関英里", "ヴァイスフリューゲル　ランドソル支部", "エルフ", "観察", 4, 43, 15, 105501, "test", "どこまでも一途に慕う、純情乙女", 7);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 25, 167, 0, "ルカ", "佐藤利奈", "トワイライトキャラバン", "ヒューマン", "釣り", 7, 54, 13, 105601, "test", "人情味溢れる粋でいなせな「姉御」", 11);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 156, 0, "ジータ", "金元寿子", "？？？", "ヒューマン", "冒険、おしゃべり", 3, 45, "", 105701, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "空への冒険を夢見る騎空士の少女", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 156, 0, "ペコリーヌ", "M・A・O", "美食殿", "ヒューマン", "食べ歩き、料理", 3, 46, 1, 105801, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", 31);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 11, 140, 0, "コッコロ", "伊藤美来", "美食殿", "エルフ", "瞑想、動植物の飼育", 5, 35, 1, 105901, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", 11);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 152, 0, "キャル", "立花理香", "美食殿", "獣人族", "猫と遊ぶ", 9, 39, 1, 106001, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", 2);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 148, 0, "ムイミ", "潘めぐみ", "？？？", "ヒューマン", "冒険、思い出話", 8, 40, "", 106101, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", 11);
