INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 11, 140, 0, "コッコロ（サマー）", "伊藤美来", "美食殿", "エルフ", "瞑想、動植物の飼育", 5, 35, 1, 107601, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", 11);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 15, 154, 0, "スズメ（サマー）", "悠木碧", "サレンディア救護院", "ヒューマン", "ご奉仕", 12, 43, 9, 107701, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", 12);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 152, 0, "キャル（サマー）", "立花理香", "美食殿", "獣人族", "猫と遊ぶ", 9, 39, 1, 107801, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", 2);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 19, 158, 0, "タマキ（サマー）", "沼倉愛美", "メルクリウス財団", "獣人族", "猫とたわむれること", 3, 48, 12, 107901, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 1);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 20, 163, 0, "ミフユ（サマー）", "田所あずさ", "メルクリウス財団", "ヒューマン", "傭兵などのアルバイト", 11, 49, 12, 108001, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", 11);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 157, 0, "シノブ（ハロウィン）", "大坪由佳", "悪魔偽王国軍（ディアボロス）", "魔族", "占い", 12, 42, 7, 108101, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 130, 0, "ミヤコ（ハロウィン）", "雨宮天", "悪魔偽王国軍（ディアボロス）", "魔族", "プリンを食べること", 1, 32, 7, 108201, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", 23);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 11, 120, 0, "ミサキ（ハロウィン）", "久野美咲", "ルーセント学院", "魔族", "ファッション誌鑑賞、コスメ集め", 1, 22, 14, 108301, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 163, 0, "チカ（クリスマス）", "福原綾香", "カルミナ", "ヒューマン", "各種楽器", 6, 46, 4, 108401, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 12, 150, 0, "クルミ（クリスマス）", "植田佳奈", "サレンディア救護院", "ヒューマン", "観劇、おままごと", 6, 40, 9, 108501, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", 9);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 148, 0, "アヤネ（クリスマス）", "芹澤優", "サレンディア救護院", "ヒューマン", "屋内でできる遊び", 5, 38, 9, 108601, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 16, 155, 0, "ヒヨリ（ニューイヤー）", "東山奈央", "トゥインクルウィッシュ", "獣人族", "人助け、応援", 8, 44, 2, 108701, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 27);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 158, 0, "ユイ（ニューイヤー）", "種田梨沙", "トゥインクルウィッシュ", "ヒューマン", "料理、人間観察", 4, 47, 2, 108801, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 5);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 18, 163, 0, "レイ（ニューイヤー）", "早見沙織", "トゥインクルウィッシュ", "魔族", "読書、乗馬、お茶", 1, 46, 2, 108901, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 12);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 16, 154, 0, "エリコ（バレンタイン）", "橋本ちなみ", "トワイライトキャラバン", "魔族", "実験、裁縫、料理", 7, 43, 13, 109001, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", 30);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 168, 0, "シズル（バレンタイン）", "生天目仁美", "ラビリンス", "ヒューマン", "家事全般", 10, 54, 3, 109101, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 24);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 17, 156, 0, "アン", "日笠陽子", "？？？", "ヒューマン", "読書", 12, 55, "", 109201, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "英霊と契約を結んだマナリアの天才王女", 1);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 144, 0, "ルゥ", "こやまきみこ", "？？？", "ヒューマン", "食べること、眠ること", 2, 45, "", 109301, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "マナリア魔法学院の新入生", 4);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 167, 0, "グレア", "福原綾香", "？？？", "半人半竜", "ピアノ", 11, 67, "", 109401, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "人を超越した力を有す心優しい竜姫", 3);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 157, 0, "クウカ（オーエド）", "長妻樹里", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "小説を読むこと", 11, 49, 15, 109501, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", 19);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 163, 0, "ニノン（オーエド）", "佐藤聡美", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "忍法開発", 8, 51, 15, 109601, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", 31);
