INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 19, 158, 0, "タマキ（作業服）", "沼倉愛美", "メルクリウス財団", "獣人族", "猫とたわむれること", 3, 48, 12, 116801, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", 1);
