INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 163, 0, "チカ（サマー）", "福原綾香", "カルミナ", "ヒューマン", "各種楽器", 6, 46, 4, 117301, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 3);
