INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 27, 166, 0, "ミツキ（オーエド）", "三石琴乃", "トワイライトキャラバン", "ヒューマン", "研究、実験", 3, 53, 13, 117501, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", 7);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 150, 0, "ユキ（オーエド）", "大空直美", "ヴァイスフリューゲル　ランドソル支部", "エルフ", "鏡で自分を見ること", 10, 40, 15, 117601, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", 10);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 158, 0, "カオリ（ハロウィン）", "高森奈津美", "自警団（カォン）", "獣人族", "踊り、空手", 7, 53, 10, 117701, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", 7);
