INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 159, 0, "アンナ（パイレーツ）", "髙野麻美", "トワイライトキャラバン", "魔族", "小説執筆", 7, 45, 13, 121901, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", 5);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 157, 0, "シノブ（パイレーツ）", "大坪由佳", "悪魔偽王国軍（ディアボロス）", "魔族", "占い", 12, 42, 7, 122001, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", 22);
