INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 16, 155, 0, "ヒヨリ（サマー）", "東山奈央", "トゥインクルウィッシュ", "獣人族", "人助け、応援", 8, 44, 2, 122401, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 27);
